// WF02b step 1 — expand files[] from WF01 into N items, one per PDF statement.
const inp = $input.first() && $input.first().json;
if (!inp) return [];
const files = (inp.files || []);
return files.map(f => ({ json: f }));

// WF02b step 2 — hash PDF binary + emit base64 for the Anthropic document block.
const crypto = require('crypto');
const meta = $('Expand Statements').item.json;
let hash = '';
let pdfBase64 = '';
let fsize = 0;
try {
  if ($binary && $binary.data) {
    const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
    hash = crypto.createHash('md5').update(buffer).digest('hex');
    pdfBase64 = buffer.toString('base64');
    fsize = ($binary.data.bytes && Number($binary.data.bytes)) || buffer.length;
  } else {
    hash = 'md5_no_binary';
  }
} catch (e) {
  hash = 'md5_compute_failed:' + e.message.slice(0, 80);
}
return { json: { ...meta, statement_id: hash, pdf_base64: pdfBase64, file_size: fsize } };

// WF02b step 3 — assemble Anthropic Messages request with up to 6 PDFs as document blocks.
// System prompt teaches Claude the bank-specific formats + category taxonomy from the sheet.
const statements = $('Compute MD5 + base64').all().map(i => i.json)
  .filter(s => s.statement_id && s.pdf_base64 && s.pdf_base64.length > 100);

const categoryRows = $('Read Categories').all().map(i => i.json);
const categoryList = categoryRows.length === 0
  ? '(no categories configured — operator should seed categories tab)'
  : categoryRows.map(r => {
      const kw = r.keywords ? ` — keywords: ${r.keywords}` : '';
      return `- ${r.id} (${r.name_ua})${kw}`;
    }).join('\n');

const systemText = `You are a Ukrainian bank statement parser. For EACH PDF below, extract every transaction row.

OUTPUT STRICT JSON, NO PROSE, NO MARKDOWN FENCE:
{
  "statements": [
    {
      "statement_id": "<the id provided in the user message>",
      "bank": "Privat24" | "Mono" | "Raiffeisen" | "ПУМБ" | "А-Банк" | "generic",
      "period_start": "YYYY-MM-DD",
      "period_end": "YYYY-MM-DD",
      "currency": "UAH" | "USD" | "EUR" | ...,
      "opening_balance": <number> | null,
      "closing_balance": <number> | null,
      "transactions": [
        {
          "date": "YYYY-MM-DD",
          "description": "<raw description from statement>",
          "counterparty": "<extracted name/IBAN>" | null,
          "amount": <positive number>,
          "currency": "<UAH/USD/EUR>",
          "debit_credit": "debit" | "credit",
          "balance_after": <number> | null,
          "category": "<one of category IDs below>",
          "confidence": <0.0..1.0>
        }
      ]
    }
  ]
}

CATEGORIES (assign per transaction by understanding the description):
${categoryList}

BANK HINTS:
- Privat24: Дата|Сума|Призначення|Залишок. Debit shown with minus prefix. Comma as decimal separator (e.g., 245,50).
- Mono (monobank): Date|Description|Amount|Balance. Credit shown with + prefix. Standard table.
- Raiffeisen: Дата операції|Опис|Сума,грн|Залишок. MCC code may appear in parens.
- ПУМБ: Дата|Контрагент|Призначення|Сума|Залишок. Two-line descriptions OK; treat as one logical transaction.
- А-Банк: Дата|Опис|Сума|Валюта|Залишок. Separate debit/credit columns common.
- generic: parse what you see; output bank: "generic".

RULES:
- Amounts: output as POSITIVE numbers; use debit_credit field for direction.
- Categories: use the ID (lowercase English), not the name_ua. If unsure, use "other".
- Confidence: reflects category-assignment certainty. >= 0.8 = confident; < 0.8 will be flagged for manual review in the Excel.
- Dates: ISO YYYY-MM-DD. Convert from any bank-specific format.
- Languages: descriptions may mix uk/ru/en — preserve original.
- DO NOT INVENT TRANSACTIONS. If a row looks malformed/unreadable, skip it.
- DO NOT OUTPUT TEXT OUTSIDE THE JSON.`;

const content = [];
for (const s of statements) {
  content.push({ type: 'text', text: `--- STATEMENT ${s.statement_id} (file: ${(s.file && s.file.file_name) || 'unknown'}) ---` });
  content.push({
    type: 'document',
    source: {
      type: 'base64',
      media_type: 'application/pdf',
      data: s.pdf_base64
    }
  });
}
content.push({ type: 'text', text: 'Extract all transactions from the above statements per the schema in the system prompt.' });

return [{
  json: {
    body: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 32768,
      system: [{ type: 'text', text: systemText, cache_control: { type: 'ephemeral' } }],
      messages: [{ role: 'user', content }]
    },
    statements: statements.map(s => ({ session_id: s.session_id, statement_id: s.statement_id, chat_id: s.chat_id, file: s.file, received_at_ms: s.received_at_ms })),
    systemText,
    categoryList
  }
}];

// WF02b step 5 — parse Haiku response, compute per-statement mean confidence, flag for Sonnet retry.
const httpResp = $input.first().json;
const buildOutput = $('Build Extraction Request').first().json;
const inputStatements = buildOutput.statements || [];

let parsed = null;
let parseError = null;
try {
  const text = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
  const cleaned = text.replace(/^```(?:json)?\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

const haikuByStmtId = {};
if (parsed && Array.isArray(parsed.statements)) {
  for (const s of parsed.statements) {
    if (s.statement_id) haikuByStmtId[s.statement_id] = s;
  }
}

const merged = inputStatements.map(inp => {
  const haikuS = haikuByStmtId[inp.statement_id];
  if (!haikuS) {
    return {
      ...inp,
      bank: 'unknown',
      period_start: null,
      period_end: null,
      currency: null,
      opening_balance: null,
      closing_balance: null,
      transactions: [],
      mean_confidence: 0,
      needs_retry: true,
      error: parseError ? `haiku_parse_failed:${parseError.slice(0, 80)}` : 'haiku_missing_statement'
    };
  }
  const txs = Array.isArray(haikuS.transactions) ? haikuS.transactions : [];
  const meanConf = txs.length === 0 ? 0
    : txs.reduce((sum, t) => sum + (typeof t.confidence === 'number' ? t.confidence : 0), 0) / txs.length;
  return {
    ...inp,
    bank: haikuS.bank || 'generic',
    period_start: haikuS.period_start || null,
    period_end: haikuS.period_end || null,
    currency: haikuS.currency || null,
    opening_balance: typeof haikuS.opening_balance === 'number' ? haikuS.opening_balance : null,
    closing_balance: typeof haikuS.closing_balance === 'number' ? haikuS.closing_balance : null,
    transactions: txs.map(t => ({ ...t, model_used: 'haiku-4.5' })),
    mean_confidence: meanConf,
    needs_retry: meanConf < 0.7 && txs.length > 0,
    error: null
  };
});

const needs_retry_any = merged.some(s => s.needs_retry);

return [{
  json: {
    statements: merged,
    needs_retry: needs_retry_any,
    usage_haiku: httpResp.usage || {},
    parse_error_haiku: parseError,
    systemText: buildOutput.systemText
  }
}];

// WF02b step 7 — Sonnet retry on flagged statements. Pull pdf_base64 from upstream MD5 node.
const md5Items = $('Compute MD5 + base64').all().map(i => i.json);
const pdfByStmtId = {};
for (const m of md5Items) {
  if (m.statement_id) pdfByStmtId[m.statement_id] = m.pdf_base64;
}

const inp = $input.first().json;
const statements = inp.statements;
const retryStmts = statements.filter(s => s.needs_retry);

const content = [];
for (const s of retryStmts) {
  const pdfBase64 = pdfByStmtId[s.statement_id];
  if (!pdfBase64) continue;
  content.push({ type: 'text', text: `--- STATEMENT ${s.statement_id} ---` });
  content.push({
    type: 'document',
    source: { type: 'base64', media_type: 'application/pdf', data: pdfBase64 }
  });
}
content.push({ type: 'text', text: 'Re-extract transactions from the above statements with higher precision per the schema in the system prompt.' });

return [{
  json: {
    body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 32768,
      system: [{ type: 'text', text: inp.systemText, cache_control: { type: 'ephemeral' } }],
      messages: [{ role: 'user', content }]
    },
    statements,
    retryStatementIds: retryStmts.map(s => s.statement_id),
    usage_haiku: inp.usage_haiku,
    parse_error_haiku: inp.parse_error_haiku
  }
}];

// WF02b step 9 — merge Sonnet retry results back into the statements array.
const httpResp = $input.first().json;
const buildOutput = $('Build Sonnet Request').first().json;
const allStatements = buildOutput.statements || [];

let parsed = null;
let parseError = null;
try {
  const text = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
  const cleaned = text.replace(/^```(?:json)?\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

const sonnetByStmtId = {};
if (parsed && Array.isArray(parsed.statements)) {
  for (const s of parsed.statements) {
    if (s.statement_id) sonnetByStmtId[s.statement_id] = s;
  }
}

const merged = allStatements.map(s => {
  if (!s.needs_retry || !sonnetByStmtId[s.statement_id]) return s;
  const sonnetS = sonnetByStmtId[s.statement_id];
  const txs = Array.isArray(sonnetS.transactions) ? sonnetS.transactions : [];
  const meanConf = txs.length === 0 ? 0
    : txs.reduce((sum, t) => sum + (typeof t.confidence === 'number' ? t.confidence : 0), 0) / txs.length;
  return {
    ...s,
    bank: sonnetS.bank || s.bank,
    period_start: sonnetS.period_start || s.period_start,
    period_end: sonnetS.period_end || s.period_end,
    currency: sonnetS.currency || s.currency,
    opening_balance: typeof sonnetS.opening_balance === 'number' ? sonnetS.opening_balance : s.opening_balance,
    closing_balance: typeof sonnetS.closing_balance === 'number' ? sonnetS.closing_balance : s.closing_balance,
    transactions: txs.map(t => ({ ...t, model_used: 'sonnet-4.6' })),
    mean_confidence: meanConf,
    needs_retry: false
  };
});

return [{
  json: {
    statements: merged,
    usage_haiku: buildOutput.usage_haiku || {},
    usage_sonnet: httpResp.usage || {},
    parse_error_haiku: buildOutput.parse_error_haiku || null,
    parse_error_sonnet: parseError
  }
}];
